export const coursesCount = coursesCatalogue.length;

export const getCourseBySlug = (slug: string): CourseListing | undefined =>
  coursesCatalogue.find((course) => course.slug === slug);

export const getAllCourseSlugs = (): string[] => coursesCatalogue.map((course) => course.slug);

// Legacy Open edX id, e.g. "course-v1:Artemat+MC10_RES4CITY+2025_T01", as used by the old
// external URLs. Resolved from each course's externalUrl so old links can redirect locally.
export const getCourseByLegacyId = (legacyId: string): CourseListing | undefined => {
  // `+` in the path can arrive decoded as a space; normalise both sides before matching.
  const id = legacyId.trim().replace(/\s+/g, "+");
  return coursesCatalogue.find((course) => course.externalUrl.replace(/\s+/g, "+").includes(`/courses/${id}`));
};
